Each number gives two choices: include it in the chosen subset or skip it. The recursive function keeps the remaining sum and the next index.

Without saved results, the same states can be checked many times. The `memo` table stores the answer for each `(index, remaining)` pair. A total of zero is an immediate success, while a negative remaining value is not useful.

An empty array has total `0`, so it is treated as a valid partition here. An odd total returns `false` before recursion starts.

```java
class Solution {
    private Boolean[][] memo;
    private int[] values;

    public boolean equalPartition(int n, int[] arr) {
        values = arr;
        int total = 0;
        for (int value : arr) {
            total += value;
        }

        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        memo = new Boolean[n + 1][target + 1];
        return canMake(0, target);
    }

    private boolean canMake(int index, int remaining) {
        if (remaining == 0) {
            return true;
        }
        if (index == values.length || remaining < 0) {
            return false;
        }
        if (memo[index][remaining] != null) {
            return memo[index][remaining];
        }

        boolean take = canMake(index + 1, remaining - values[index]);
        boolean skip = canMake(index + 1, remaining);
        memo[index][remaining] = take || skip;
        return memo[index][remaining];
    }
}
```

Time complexity: `O(n * target)` because each index and remaining sum is solved once.

Space complexity: `O(n * target)` for `memo`, plus `O(n)` recursion stack.

This keeps the full table instead of compressing it to one row. `dp[i][sum]` tells whether `sum` can be formed from the first `i` values.

For every value, the table carries forward the result from skipping it, or checks the column `sum - value` when taking it. This is a little easier to inspect than the one-row version, but it uses more memory.

For `[1, 5, 11, 5]`, the total is `22`, so column `11` is the target. The table eventually marks `dp[4][11]` as true.

```cpp
#include <vector>
using namespace std;

class Solution{
public:
    bool equalPartition(int n, vector<int> arr) {
        int total = 0;
        for (int value : arr) {
            total += value;
        }

        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        vector<vector<bool>> dp(n + 1, vector<bool>(target + 1, false));

        for (int i = 0; i <= n; ++i) {
            dp[i][0] = true;
        }

        for (int i = 1; i <= n; ++i) {
            int value = arr[i - 1];
            for (int sum = 1; sum <= target; ++sum) {
                dp[i][sum] = dp[i - 1][sum];
                if (sum >= value) {
                    dp[i][sum] = dp[i][sum] || dp[i - 1][sum - value];
                }
            }
        }

        return dp[n][target];
    }
};
```

Time complexity: `O(n * target)`.

Space complexity: `O(n * target)`. The input vector is not changed.

A set makes it easy to store only the sums that have actually been reached. Start with `{0}`, then for every number add a new version of each existing sum.

The old set is copied before adding new sums. That matters because each array value must be used at most once.

Dry run for `[1, 5, 5, 11]`: the total is `22`, and the target is `11`. The reachable sums include `0, 1, 5, 6`, then `10`, `11`, and more. Finding `11` is enough because the remaining values also total `11`.

```python
class Solution:
    def equalPartition(self, n, arr):
        total = sum(arr)
        if total % 2 != 0:
            return False

        target = total // 2
        reachable = {0}

        for value in arr:
            new_sums = set(reachable)
            for current_sum in reachable:
                next_sum = current_sum + value
                if next_sum <= target:
                    new_sums.add(next_sum)
            reachable = new_sums

            if target in reachable:
                return True

        return target in reachable
```

Time complexity: `O(n * target)` in the usual bounded-sum view.

Space complexity: `O(target)` for the reachable sums. This version does not modify `arr`.

The total must be even first. After that, the task becomes checking whether some elements can make `total / 2`.

`possible[x]` means that sum `x` can be made with the numbers processed so far. The loop goes backward so one number is not used twice.

For `[1, 5, 11, 5]`, the total is `22`, so the target is `11`. After processing `1` and `5`, sums `0, 1, 5, 6` are possible. The value `11` becomes possible when `11` is processed.

```cpp
#include <vector>
using namespace std;

class Solution{
public:
    bool equalPartition(int n, vector<int> arr) {
        int total = 0;
        for (int value : arr) {
            total += value;
        }

        if (total % 2 != 0) {
            return false;
        }

        int target = total / 2;
        vector<bool> possible(target + 1, false);
        possible[0] = true;

        for (int value : arr) {
            for (int sum = target; sum >= value; --sum) {
                possible[sum] = possible[sum] || possible[sum - value];
            }
        }

        return possible[target];
    }
};
```

Time complexity: `O(n * target)`, where `target` is half of the total sum.

Space complexity: `O(target)`. The input array is passed by value, but the algorithm does not change its values.

class Solution{
public:

    bool solve(vector<int>& arr, int i, int check, vector<vector<int>>& dp){
        if(check == 0){
            return true;
        }

        if(i >= arr.size()){
            return false;
        }

        if(dp[i][check] != -1){
            return dp[i][check];
        }

        bool take = 0;
        bool skip = 0;

        if(arr[i] <= check){
            take = solve(arr, i+1, check - arr[i], dp);
        }

        skip = solve(arr, i + 1, check, dp);

        return dp[i][check] = take || skip;
    }
    bool equalPartition(int n, vector<int> arr) {

        int sum = 0;


        for(int i=0; i<n; i++){
            sum += arr[i];
        }


        int check = 0;
        if(sum % 2 == 0){
            check = sum / 2;
           vector<vector<int>> dp(n, vector<int>(sum + 1, -1));
            return solve(arr,0, check, dp);
        }else{
            return false;
        }
    }
};
